/* ============================================
   ChartPulse — Design System & Global Styles
   Dark-mode financial dashboard
   ============================================ */

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

/* ---- CSS Custom Properties (OKLCH) ---- */
:root {
  /* Brand */
  --brand-blue: oklch(50% 0.22 265);
  --brand-blue-hover: oklch(55% 0.24 265);
  --brand-blue-muted: oklch(40% 0.14 265);
  --brand-red: oklch(63% 0.22 15);
  --brand-red-muted: oklch(50% 0.15 15);
  --brand-green: oklch(65% 0.14 165);
  --brand-green-muted: oklch(45% 0.10 165);

  /* Surfaces */
  --bg-primary: oklch(10% 0.01 265);
  --bg-surface: oklch(15% 0.02 270);
  --bg-card: oklch(17% 0.02 270);
  --bg-card-hover: oklch(20% 0.02 270);
  --bg-elevated: oklch(22% 0.03 270);
  --bg-input: oklch(13% 0.01 270);

  /* Text */
  --text-primary: oklch(92% 0.01 265);
  --text-secondary: oklch(68% 0.01 265);
  --text-muted: oklch(50% 0.01 265);
  --text-accent: oklch(65% 0.20 265);
  --text-positive: oklch(72% 0.14 165);
  --text-negative: oklch(68% 0.20 15);

  /* Borders */
  --border-default: oklch(25% 0.02 270);
  --border-subtle: oklch(20% 0.01 270);
  --border-focus: oklch(50% 0.22 265);

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 8px 24px oklch(0% 0 0 / 0.5);

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'SF Mono', 'Cascadia Code', 'Consolas', monospace;

  /* Sizing */
  --nav-height: 56px;
  --sidebar-width: 280px;
  --chart-toolbar-height: 44px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Legacy hex fallbacks for chart canvas */
  --hex-bg: #0F0F0F;
  --hex-surface: #161625;
  --hex-card: #1a1a2e;
  --hex-blue: #2962FF;
  --hex-red: #F7525F;
  --hex-green: #26a69a;
  --hex-text: #e0e0e0;
  --hex-muted: #787b86;
}

/* ---- Reset ---- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a {
  color: var(--text-accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--brand-blue-hover);
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

table {
  border-collapse: collapse;
  width: 100%;
}

/* ---- Utility ---- */
.container {
  max-width: 1360px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

.text-positive { color: var(--text-positive); }
.text-negative { color: var(--text-negative); }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--text-accent); }
.text-secondary { color: var(--text-secondary); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.786rem;
  font-weight: 600;
  line-height: 1.4;
}

.badge-positive {
  background: oklch(30% 0.06 165);
  color: var(--text-positive);
}

.badge-negative {
  background: oklch(30% 0.08 15);
  color: var(--text-negative);
}

.badge-blue {
  background: oklch(30% 0.10 265);
  color: var(--text-accent);
}

.badge-neutral {
  background: oklch(25% 0.01 265);
  color: var(--text-secondary);
}

.badge-platinum {
  background: linear-gradient(135deg, oklch(75% 0.02 265), oklch(65% 0.04 265));
  color: oklch(95% 0.01 265);
}

.badge-gold {
  background: linear-gradient(135deg, oklch(75% 0.12 85), oklch(65% 0.10 75));
  color: oklch(95% 0.02 85);
}

/* ---- Navigation ---- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
  display: flex;
  align-items: center;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--text-primary);
  text-decoration: none;
}

.nav-brand svg {
  width: 28px;
  height: 28px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.nav-links a {
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 0.928rem;
  transition: all var(--transition-fast);
}

.nav-links a:hover {
  color: var(--text-primary);
  background: oklch(25% 0.02 270);
}

.nav-links a.active {
  color: var(--text-accent);
  background: oklch(25% 0.06 265);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.928rem;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--brand-blue);
  color: oklch(98% 0.01 265);
}

.btn-primary:hover {
  background: var(--brand-blue-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: oklch(25% 0.02 270);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  background: oklch(30% 0.02 270);
  border-color: var(--text-muted);
}

.btn-ghost {
  color: var(--text-secondary);
  padding: var(--space-sm) var(--space-md);
}

.btn-ghost:hover {
  color: var(--text-primary);
  background: oklch(20% 0.02 270);
}

.btn-sm {
  padding: 4px 12px;
  font-size: 0.857rem;
}

/* ---- Hero Section ---- */
.hero {
  padding: var(--space-3xl) 0;
  text-align: center;
  background: linear-gradient(180deg, oklch(15% 0.04 265) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, oklch(35% 0.12 265 / 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero h1 {
  font-size: 2.8rem;
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: var(--space-md);
  position: relative;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--brand-blue), oklch(70% 0.18 265));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.15rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto var(--space-xl);
  position: relative;
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  position: relative;
}

/* ---- Market Summary Bar ---- */
.market-summary {
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
  overflow-x: auto;
}

.market-summary-inner {
  display: flex;
  gap: 0;
  min-width: max-content;
}

.market-summary-item {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border-right: 1px solid var(--border-subtle);
  font-size: 0.857rem;
  white-space: nowrap;
}

.market-summary-item .label {
  color: var(--text-muted);
  font-weight: 500;
}

.market-summary-item .price {
  color: var(--text-primary);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.market-summary-item .change {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ---- Tabs ---- */
.tabs {
  display: flex;
  align-items: center;
  gap: 2px;
  border-bottom: 1px solid var(--border-default);
  overflow-x: auto;
}

.tab-btn {
  padding: var(--space-sm) var(--space-md);
  font-size: 0.928rem;
  font-weight: 500;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  white-space: nowrap;
  margin-bottom: -1px;
}

.tab-btn:hover {
  color: var(--text-secondary);
}

.tab-btn.active {
  color: var(--text-accent);
  border-bottom-color: var(--brand-blue);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* ---- Section ---- */
.section {
  padding: var(--space-xl) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.section-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

.section-link {
  font-size: 0.857rem;
  font-weight: 500;
  color: var(--text-accent);
  display: flex;
  align-items: center;
  gap: 4px;
}

.section-link:hover {
  text-decoration: underline;
}

/* ---- Card ---- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.card:hover {
  border-color: var(--border-default);
}

.card-header {
  padding: var(--space-md) var(--space-lg);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-body {
  padding: var(--space-lg);
}

/* ---- Data Table ---- */
.data-table {
  width: 100%;
  font-size: 0.928rem;
}

.data-table th {
  text-align: left;
  padding: var(--space-sm) var(--space-md);
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.857rem;
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}

.data-table td {
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid oklch(18% 0.01 270);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.data-table tr:hover td {
  background: oklch(18% 0.01 270);
}

.data-table .ticker {
  font-weight: 600;
  color: var(--text-accent);
}

.data-table .price {
  font-weight: 600;
}

/* ---- Sparkline ---- */
.sparkline {
  display: inline-block;
  vertical-align: middle;
}

.sparkline svg {
  width: 80px;
  height: 32px;
}

.sparkline svg path,
.sparkline svg polyline {
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.sparkline.positive svg polyline { stroke: var(--brand-green); }
.sparkline.negative svg polyline { stroke: var(--brand-red); }
.sparkline.positive svg path { fill: oklch(65% 0.14 165 / 0.1); stroke: none; }
.sparkline.negative svg path { fill: oklch(63% 0.22 15 / 0.1); stroke: none; }

/* ---- Idea Card ---- */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-fast);
}

.idea-card:hover {
  border-color: oklch(30% 0.04 270);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.idea-card-img {
  width: 100%;
  height: 180px;
  background: var(--bg-elevated);
  position: relative;
  overflow: hidden;
}

.idea-card-img svg {
  width: 100%;
  height: 100%;
}

.idea-card-body {
  padding: var(--space-md);
}

.idea-card-author {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.idea-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--brand-blue-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: oklch(85% 0.10 265);
}

.idea-card-title {
  font-size: 0.928rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
  line-height: 1.4;
}

.idea-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.786rem;
  color: var(--text-muted);
}

.idea-card-tags {
  display: flex;
  gap: var(--space-xs);
  margin-top: var(--space-sm);
}

.idea-tag {
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.714rem;
  font-weight: 500;
  background: oklch(22% 0.02 270);
  color: var(--text-secondary);
}

/* ---- Indicator Card ---- */
.indicator-card {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  transition: border-color var(--transition-fast);
}

.indicator-card:hover {
  border-color: var(--border-default);
}

.indicator-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: oklch(25% 0.06 265);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.indicator-info {
  flex: 1;
  min-width: 0;
}

.indicator-name {
  font-size: 0.928rem;
  font-weight: 600;
}

.indicator-desc {
  font-size: 0.786rem;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Trending Stocks Grid ---- */
.trending-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-sm);
}

.trending-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.trending-item:hover {
  border-color: var(--border-default);
  background: var(--bg-card-hover);
}

.trending-item .ticker {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-accent);
}

.trending-item .price {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.trending-item .change {
  font-weight: 600;
  font-size: 0.857rem;
  font-variant-numeric: tabular-nums;
}

/* ---- Grid Layouts ---- */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

/* ---- Chart Page Layout ---- */
.chart-workspace {
  display: grid;
  grid-template-columns: var(--sidebar-width) 1fr;
  height: calc(100vh - var(--nav-height));
  overflow: hidden;
}

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
  height: var(--chart-toolbar-height);
  overflow-x: auto;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 var(--space-xs);
}

.toolbar-group + .toolbar-group {
  border-left: 1px solid var(--border-subtle);
  padding-left: var(--space-sm);
}

.toolbar-btn {
  padding: 4px 10px;
  font-size: 0.786rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.toolbar-btn:hover {
  color: var(--text-secondary);
  background: oklch(22% 0.02 270);
}

.toolbar-btn.active {
  color: var(--text-accent);
  background: oklch(25% 0.06 265);
}

.chart-canvas {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  min-height: 0;
}

.chart-canvas svg {
  width: 100%;
  height: 100%;
}

.chart-detail-panel {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  max-height: 320px;
  overflow-y: auto;
}

.detail-header {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
}

.detail-ticker {
  font-size: 1.3rem;
  font-weight: 800;
}

.detail-company {
  font-size: 0.928rem;
  color: var(--text-secondary);
}

.detail-exchange {
  font-size: 0.786rem;
  color: var(--text-muted);
  padding: 2px 8px;
  background: oklch(20% 0.01 270);
  border-radius: var(--radius-sm);
}

.detail-price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-md);
  padding: var(--space-sm) var(--space-md);
}

.detail-price {
  font-size: 2rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.detail-change {
  font-size: 1rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.detail-stats {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md);
}

.detail-stat {
  display: flex;
  justify-content: space-between;
  padding: var(--space-xs) 0;
  border-bottom: 1px solid oklch(16% 0.01 270);
  font-size: 0.857rem;
}

.detail-stat .label {
  color: var(--text-muted);
}

.detail-stat .value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ---- Watchlist Sidebar ---- */
.watchlist {
  background: var(--bg-surface);
  border-right: 1px solid var(--border-subtle);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.watchlist-header {
  padding: var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-title {
  font-size: 1rem;
  font-weight: 700;
}

.watchlist-search {
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
}

.watchlist-search input {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.857rem;
  outline: none;
  transition: border-color var(--transition-fast);
}

.watchlist-search input:focus {
  border-color: var(--brand-blue);
}

.watchlist-search input::placeholder {
  color: var(--text-muted);
}

.watchlist-group {
  border-bottom: 1px solid var(--border-subtle);
}

.watchlist-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  cursor: pointer;
  user-select: none;
  transition: background var(--transition-fast);
}

.watchlist-group-header:hover {
