/* ============================================
   ChartPulse — Design System & Global Styles
   Dark-mode financial dashboard
   ============================================ */

/* Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

/* ---- CSS Custom Properties (OKLCH) ---- */
:root {
  /* Brand */
  --brand-blue: oklch(50% 0.22 265);
  --brand-blue-hover: oklch(55% 0.24 265);
  --brand-blue-muted: oklch(40% 0.14 265);
  --brand-red: oklch(63% 0.22 15);
  --brand-red-muted: oklch(50% 0.15 15);
  --brand-green: oklch(65% 0.14 165);
  --brand-green-muted: oklch(45% 0.10 165);

  /* Surfaces */
  --bg-primary: oklch(10% 0.01 265);
  --bg-surface: oklch(15% 0.02 270);
  --bg-card: oklch(17% 0.02 270);
  --bg-card-hover: oklch(20% 0.02 270);
  --bg-elevated: oklch(22% 0.03 270);
  --bg-input: oklch(13% 0.01 270);

  /* Text */
  --text-primary: oklch(92% 0.01 265);
  --text-secondary: oklch(68% 0.01 265);
  --text-muted: oklch(50% 0.01 265);
  --text-accent: oklch(65% 0.20 265);
  --text-positive: oklch(72% 0.14 165);
  --text-negative: oklch(68% 0.20 15);

  /* Borders */
  --border-default: oklch(25% 0.02 270);
  --border-subtle: oklch(20% 0.01 270);
  --border-focus: oklch(50% 0.22 265);

  /* Shadows */
  --shadow-sm: 0 1px 2px oklch(0% 0 0 / 0.3);
  --shadow-md: 0 4px 12px oklch(0% 0 0 / 0.4);
  --shadow-lg: 0 8px 24px oklch(0% 0 0 / 0.5);

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;

  /* Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-xl: 16px;

  /* Typography */
  --font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: 'SF Mono', 'Cascadia Code', 'Consolas', monospace;

  /* Sizing */
  --nav-height: 56px;
  --sidebar-width: 280px;
  --chart-toolbar-height: 44px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;

  /* Legacy hex fallbacks for chart canvas */
  --hex-bg: #0F0F0F;
  --hex-surface: #161625;
  --hex-card: #1a1a2e;
  --hex-blue: #2962FF;
  --hex-red: #F7525F;
  --hex-green: #26a69a;
  --hex-text: #e0e0e0;
  --hex-muted: #787b86;
}

/* ---- Reset ---- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-family);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.5;
  min-height: 100vh;
  overflow-x: hidden;
}

a {
  color: var(--text-accent);
  text-decoration: none;
  transition: color var(--transition-fast);
}

a:hover {
  color: var(--brand-blue-hover);
}

img {
  max-width: 100%;
  display: block;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
  color: inherit;
  font-size: inherit;
}

ul, ol {
  list-style: none;
}

table {
  border-collapse: collapse;
  width: 100%;
}

/* ---- Utility ---- */
.container {
  max-width: 1360px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
}

.text-positive { color: var(--text-positive); }
.text-negative { color: var(--text-negative); }
.text-muted { color: var(--text-muted); }
.text-accent { color: var(--text-accent); }
.text-secondary { color: var(--text-secondary); }

.badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.786rem;
  font-weight: 600;
  line-height: 1.4;
}

.badge-positive {
  background: oklch(30% 0.06 165);
  color: var(--text-positive);
}

.badge-negative {
  background: oklch(30% 0.08 15);
  color: var(--text-negative);
}

.badge-blue {
  background: oklch(30% 0.10 265);
  color: var(--text-accent);
}

.badge-neutral {
  background: oklch(25% 0.01 265);
  color: var(--text-secondary);
}

.badge-platinum {
  background: linear-gradient(135deg, oklch(75% 0.02 265), oklch(65% 0.04 265));
  color: oklch(95% 0.01 265);
}

.badge-gold {
  background: linear-gradient(135deg, oklch(75% 0.12 85), oklch(65% 0.10 75));
  color: oklch(95% 0.02 85);
}

/* ---- Navigation ---- */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--nav-height);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
  display: flex;
  align-items: center;
}

.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  max-width: 1440px;
  margin: 0 auto;
  padding: 0 var(--space-lg);
}

.nav-brand {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-weight: 700;
  font-size: 1.2rem;
  color: var(--text-primary);
  text-decoration: none;
}

.nav-brand svg {
  width: 28px;
  height: 28px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
}

.nav-links a {
  padding: var(--space-sm) var(--space-md);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  font-weight: 500;
  font-size: 0.928rem;
  transition: all var(--transition-fast);
}

.nav-links a:hover {
  color: var(--text-primary);
  background: oklch(25% 0.02 270);
}

.nav-links a.active {
  color: var(--text-accent);
  background: oklch(25% 0.06 265);
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-lg);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.928rem;
  transition: all var(--transition-fast);
  white-space: nowrap;
}

.btn-primary {
  background: var(--brand-blue);
  color: oklch(98% 0.01 265);
}

.btn-primary:hover {
  background: var(--brand-blue-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: oklch(25% 0.02 270);
  color: var(--text-primary);
  border: 1px solid var(--border-default);
}

.btn-secondary:hover {
  background: oklch(30% 0.02 270);
  border-color: var(--text-muted);
}

.btn-ghost {
  color: var(--text-secondary);
  padding: var(--space-sm) var(--space-md);
}

.btn-ghost:hover {
  color: var(--text-primary);
  background: oklch(20% 0.02 270);
}

.btn-sm {
  padding: 4px 12px;
  font-size: 0.857rem;
}

/* ---- Hero Section ---- */
.hero {
  padding: var(--space-3xl) 0;
  text-align: center;
  background: linear-gradient(180deg, oklch(15% 0.04 265) 0%, var(--bg-primary) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, oklch(35% 0.12 265 / 0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero h1 {
  font-size: 2.8rem;
  font-weight: 800;
  line-height: 1.15;
  margin-bottom: var(--space-md);
  position: relative;
}

.hero h1 span {
  background: linear-gradient(135deg, var(--brand-blue), oklch(70% 0.18 265));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.hero p {
  font-size: 1.15rem;
  color: var(--text-secondary);
  max-width: 640px;
  margin: 0 auto var(--space-xl);
  position: relative;
}

.hero-actions {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  position: relative;
}

/* ---- Market Summary Bar ---- */
.market-summary {
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
  overflow-x: auto;
}

.market-summary-inner {
  display: flex;
  gap: 0;
  min-width: max-content;
}

.market-summary-item {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border-right: 1px solid var(--border-subtle);
  font-size: 0.857rem;
  white-space: nowrap;
}

.market-summary-item .label {
  color: var(--text-muted);
  font-weight: 500;
}

.market-summary-item .price {
  color: var(--text-primary);
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.market-summary-item .change {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ---- Tabs ---- */
.tabs {
  display: flex;
  align-items: center;
  gap: 2px;
  border-bottom: 1px solid var(--border-default);
  overflow-x: auto;
}

.tab-btn {
  padding: var(--space-sm) var(--space-md);
  font-size: 0.928rem;
  font-weight: 500;
  color: var(--text-muted);
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
  white-space: nowrap;
  margin-bottom: -1px;
}

.tab-btn:hover {
  color: var(--text-secondary);
}

.tab-btn.active {
  color: var(--text-accent);
  border-bottom-color: var(--brand-blue);
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

/* ---- Section ---- */
.section {
  padding: var(--space-xl) 0;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-lg);
}

.section-title {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--text-primary);
}

.section-link {
  font-size: 0.857rem;
  font-weight: 500;
  color: var(--text-accent);
  display: flex;
  align-items: center;
  gap: 4px;
}

.section-link:hover {
  text-decoration: underline;
}

/* ---- Card ---- */
.card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: border-color var(--transition-fast);
}

.card:hover {
  border-color: var(--border-default);
}

.card-header {
  padding: var(--space-md) var(--space-lg);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-body {
  padding: var(--space-lg);
}

/* ---- Data Table ---- */
.data-table {
  width: 100%;
  font-size: 0.928rem;
}

.data-table th {
  text-align: left;
  padding: var(--space-sm) var(--space-md);
  color: var(--text-muted);
  font-weight: 500;
  font-size: 0.857rem;
  border-bottom: 1px solid var(--border-subtle);
  white-space: nowrap;
}

.data-table td {
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid oklch(18% 0.01 270);
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.data-table tr:hover td {
  background: oklch(18% 0.01 270);
}

.data-table .ticker {
  font-weight: 600;
  color: var(--text-accent);
}

.data-table .price {
  font-weight: 600;
}

/* ---- Sparkline ---- */
.sparkline {
  display: inline-block;
  vertical-align: middle;
}

.sparkline svg {
  width: 80px;
  height: 32px;
}

.sparkline svg path,
.sparkline svg polyline {
  fill: none;
  stroke-width: 1.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.sparkline.positive svg polyline { stroke: var(--brand-green); }
.sparkline.negative svg polyline { stroke: var(--brand-red); }
.sparkline.positive svg path { fill: oklch(65% 0.14 165 / 0.1); stroke: none; }
.sparkline.negative svg path { fill: oklch(63% 0.22 15 / 0.1); stroke: none; }

/* ---- Idea Card ---- */
.idea-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all var(--transition-fast);
}

.idea-card:hover {
  border-color: oklch(30% 0.04 270);
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.idea-card-img {
  width: 100%;
  height: 180px;
  background: var(--bg-elevated);
  position: relative;
  overflow: hidden;
}

.idea-card-img svg {
  width: 100%;
  height: 100%;
}

.idea-card-body {
  padding: var(--space-md);
}

.idea-card-author {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-sm);
}

.idea-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--brand-blue-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.75rem;
  font-weight: 700;
  color: oklch(85% 0.10 265);
}

.idea-card-title {
  font-size: 0.928rem;
  font-weight: 600;
  margin-bottom: var(--space-xs);
  line-height: 1.4;
}

.idea-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  font-size: 0.786rem;
  color: var(--text-muted);
}

.idea-card-tags {
  display: flex;
  gap: var(--space-xs);
  margin-top: var(--space-sm);
}

.idea-tag {
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.714rem;
  font-weight: 500;
  background: oklch(22% 0.02 270);
  color: var(--text-secondary);
}

/* ---- Indicator Card ---- */
.indicator-card {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  transition: border-color var(--transition-fast);
}

.indicator-card:hover {
  border-color: var(--border-default);
}

.indicator-icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: oklch(25% 0.06 265);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.indicator-info {
  flex: 1;
  min-width: 0;
}

.indicator-name {
  font-size: 0.928rem;
  font-weight: 600;
}

.indicator-desc {
  font-size: 0.786rem;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ---- Trending Stocks Grid ---- */
.trending-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-sm);
}

.trending-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  transition: all var(--transition-fast);
}

.trending-item:hover {
  border-color: var(--border-default);
  background: var(--bg-card-hover);
}

.trending-item .ticker {
  font-weight: 700;
  font-size: 1rem;
  color: var(--text-accent);
}

.trending-item .price {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.trending-item .change {
  font-weight: 600;
  font-size: 0.857rem;
  font-variant-numeric: tabular-nums;
}

/* ---- Grid Layouts ---- */
.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-lg);
}

.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-lg);
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-lg);
}

/* ---- Chart Page Layout ---- */
.chart-workspace {
  display: grid;
  grid-template-columns: var(--sidebar-width) 1fr;
  height: calc(100vh - var(--nav-height));
  overflow: hidden;
}

.chart-main {
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.chart-toolbar {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-subtle);
  height: var(--chart-toolbar-height);
  overflow-x: auto;
}

.toolbar-group {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 0 var(--space-xs);
}

.toolbar-group + .toolbar-group {
  border-left: 1px solid var(--border-subtle);
  padding-left: var(--space-sm);
}

.toolbar-btn {
  padding: 4px 10px;
  font-size: 0.786rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.toolbar-btn:hover {
  color: var(--text-secondary);
  background: oklch(22% 0.02 270);
}

.toolbar-btn.active {
  color: var(--text-accent);
  background: oklch(25% 0.06 265);
}

.chart-canvas {
  flex: 1;
  background: var(--bg-primary);
  position: relative;
  min-height: 0;
}

.chart-canvas svg {
  width: 100%;
  height: 100%;
}

.chart-detail-panel {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  max-height: 320px;
  overflow-y: auto;
}

.detail-header {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  padding: var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
}

.detail-ticker {
  font-size: 1.3rem;
  font-weight: 800;
}

.detail-company {
  font-size: 0.928rem;
  color: var(--text-secondary);
}

.detail-exchange {
  font-size: 0.786rem;
  color: var(--text-muted);
  padding: 2px 8px;
  background: oklch(20% 0.01 270);
  border-radius: var(--radius-sm);
}

.detail-price-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-md);
  padding: var(--space-sm) var(--space-md);
}

.detail-price {
  font-size: 2rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.detail-change {
  font-size: 1rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.detail-stats {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md);
}

.detail-stat {
  display: flex;
  justify-content: space-between;
  padding: var(--space-xs) 0;
  border-bottom: 1px solid oklch(16% 0.01 270);
  font-size: 0.857rem;
}

.detail-stat .label {
  color: var(--text-muted);
}

.detail-stat .value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ---- Watchlist Sidebar ---- */
.watchlist {
  background: var(--bg-surface);
  border-right: 1px solid var(--border-subtle);
  overflow-y: auto;
  display: flex;
  flex-direction: column;
}

.watchlist-header {
  padding: var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.watchlist-title {
  font-size: 1rem;
  font-weight: 700;
}

.watchlist-search {
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid var(--border-subtle);
}

.watchlist-search input {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-input);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  color: var(--text-primary);
  font-size: 0.857rem;
  outline: none;
  transition: border-color var(--transition-fast);
}

.watchlist-search input:focus {
  border-color: var(--brand-blue);
}

.watchlist-search input::placeholder {
  color: var(--text-muted);
}

.watchlist-group {
  border-bottom: 1px solid var(--border-subtle);
}

.watchlist-group-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  cursor: pointer;
  user-select: none;
  transition: background var(--transition-fast);
}

.watchlist-group-header:hover {
  background: oklch(18% 0.01 270);
}

.watchlist-group-header .group-name {
  font-size: 0.857rem;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}

.watchlist-group-header .arrow {
  color: var(--text-muted);
  transition: transform var(--transition-fast);
  font-size: 0.714rem;
}

.watchlist-group.collapsed .arrow {
  transform: rotate(-90deg);
}

.watchlist-group.collapsed .watchlist-group-items {
  display: none;
}

.watchlist-row {
  display: grid;
  grid-template-columns: 1fr auto auto;
  gap: var(--space-sm);
  padding: var(--space-xs) var(--space-md);
  align-items: center;
  cursor: pointer;
  transition: background var(--transition-fast);
  font-size: 0.857rem;
}

.watchlist-row:hover {
  background: oklch(18% 0.01 270);
}

.watchlist-row.active {
  background: oklch(22% 0.04 265);
}

.watchlist-row .symbol {
  font-weight: 600;
  color: var(--text-accent);
}

.watchlist-row .last-price {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.watchlist-row .chg-pct {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  text-align: right;
  min-width: 60px;
}

/* ---- Financials ---- */
.financials-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-lg);
  padding: var(--space-md);
}

.financials-section h4 {
  font-size: 0.857rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--space-sm);
}

.financial-row {
  display: flex;
  justify-content: space-between;
  padding: var(--space-xs) 0;
  border-bottom: 1px solid oklch(16% 0.01 270);
  font-size: 0.857rem;
}

.financial-row .label {
  color: var(--text-muted);
}

.financial-row .value {
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

/* ---- News / Story Cards ---- */
.story-card {
  display: flex;
  gap: var(--space-md);
  padding: var(--space-md) 0;
  border-bottom: 1px solid oklch(18% 0.01 270);
}

.story-card:last-child {
  border-bottom: none;
}

.story-thumb {
  width: 100px;
  height: 66px;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.story-content {
  flex: 1;
  min-width: 0;
}

.story-source {
  font-size: 0.714rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: 2px;
}

.story-title {
  font-size: 0.928rem;
  font-weight: 600;
  line-height: 1.4;
  margin-bottom: 4px;
}

.story-time {
  font-size: 0.714rem;
  color: var(--text-muted);
}

/* ---- Broker Card ---- */
.broker-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  padding: var(--space-lg);
  transition: all var(--transition-fast);
}

.broker-card:hover {
  border-color: var(--border-default);
  box-shadow: var(--shadow-md);
}

.broker-top {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  margin-bottom: var(--space-md);
}

.broker-logo {
  width: 48px;
  height: 48px;
  border-radius: var(--radius-md);
  background: var(--bg-elevated);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.714rem;
  color: var(--text-accent);
  flex-shrink: 0;
}

.broker-info h3 {
  font-size: 1rem;
  font-weight: 700;
}

.broker-info .tier {
  font-size: 0.786rem;
  margin-top: 2px;
}

.broker-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-md);
  margin-bottom: var(--space-md);
}

.broker-stat {
  text-align: center;
}

.broker-stat .stat-value {
  font-size: 1.15rem;
  font-weight: 700;
}

.broker-stat .stat-label {
  font-size: 0.714rem;
  color: var(--text-muted);
  margin-top: 2px;
}

.broker-promo {
  padding: var(--space-sm) var(--space-md);
  background: oklch(22% 0.06 265);
  border-radius: var(--radius-md);
  font-size: 0.857rem;
  font-weight: 600;
  color: var(--text-accent);
  text-align: center;
  margin-top: var(--space-sm);
}

/* ---- Stats Banner ---- */
.stats-banner {
  background: linear-gradient(135deg, oklch(20% 0.06 265), oklch(15% 0.04 265));
  padding: var(--space-2xl) 0;
  text-align: center;
  border-top: 1px solid var(--border-subtle);
  border-bottom: 1px solid var(--border-subtle);
}

.stats-grid {
  display: flex;
  justify-content: center;
  gap: var(--space-3xl);
  flex-wrap: wrap;
}

.stat-item .stat-number {
  font-size: 2.5rem;
  font-weight: 800;
  background: linear-gradient(135deg, var(--brand-blue), oklch(70% 0.18 265));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.stat-item .stat-desc {
  font-size: 1rem;
  color: var(--text-secondary);
  margin-top: var(--space-xs);
}

.stat-item .stat-tagline {
  font-size: 0.857rem;
  color: var(--text-muted);
  font-style: italic;
  margin-top: var(--space-sm);
}

/* ---- Pagination ---- */
.pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-sm);
  padding: var(--space-xl) 0;
}

.pagination button {
  width: 36px;
  height: 36px;
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 0.857rem;
  color: var(--text-muted);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  transition: all var(--transition-fast);
}

.pagination button:hover {
  border-color: var(--border-default);
  color: var(--text-primary);
}

.pagination button.active {
  background: var(--brand-blue);
  border-color: var(--brand-blue);
  color: oklch(98% 0.01 265);
}

.pagination .dots {
  color: var(--text-muted);
  font-size: 0.857rem;
}

/* ---- Footer ---- */
.footer {
  background: var(--bg-surface);
  border-top: 1px solid var(--border-subtle);
  padding: var(--space-2xl) 0 var(--space-lg);
}

.footer-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-xl);
  margin-bottom: var(--space-2xl);
}

.footer-col h4 {
  font-size: 0.857rem;
  font-weight: 700;
  color: var(--text-primary);
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-bottom: var(--space-md);
}

.footer-col a {
  display: block;
  color: var(--text-muted);
  font-size: 0.857rem;
  padding: 3px 0;
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--text-primary);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-lg);
  border-top: 1px solid var(--border-subtle);
  font-size: 0.786rem;
  color: var(--text-muted);
}

/* ---- Ideas Page ---- */
.ideas-header {
  background: linear-gradient(180deg, oklch(15% 0.03 265) 0%, var(--bg-primary) 100%);
  padding: var(--space-xl) 0;
}

.ideas-filters {
  display: flex;
  align-items: center;
  gap: var(--space-md);
  flex-wrap: wrap;
}

.filter-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-md);
  font-size: 0.857rem;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all var(--transition-fast);
}

.filter-toggle:hover {
  border-color: var(--border-default);
}

.filter-toggle.active {
  border-color: var(--brand-blue);
  color: var(--text-accent);
  background: oklch(22% 0.06 265);
}

.filter-toggle .toggle-switch {
  width: 32px;
  height: 18px;
  border-radius: 9px;
  background: oklch(30% 0.01 270);
  position: relative;
  transition: background var(--transition-fast);
}

.filter-toggle.active .toggle-switch {
  background: var(--brand-blue);
}

.filter-toggle .toggle-switch::after {
  content: '';
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: oklch(90% 0.01 265);
  position: absolute;
  top: 2px;
  left: 2px;
  transition: transform var(--transition-fast);
}

.filter-toggle.active .toggle-switch::after {
  transform: translateX(14px);
}

.ideas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: var(--space-lg);
}

/* ---- Markets Page ---- */
.markets-tabs {
  position: sticky;
  top: var(--nav-height);
  z-index: 50;
  background: var(--bg-surface);
  border-bottom: 1px solid var(--border-default);
}

.markets-section {
  padding: var(--space-xl) 0;
  border-bottom: 1px solid var(--border-subtle);
}

.markets-section-title {
  font-size: 1.3rem;
  font-weight: 700;
  margin-bottom: var(--space-lg);
  display: flex;
  align-items: center;
  gap: var(--space-sm);
}

.chart-controls {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-left: auto;
}

.chart-ctrl-btn {
  padding: 3px 8px;
  font-size: 0.714rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.chart-ctrl-btn:hover {
  color: var(--text-secondary);
  background: oklch(20% 0.01 270);
}

.chart-ctrl-btn.active {
  color: var(--text-accent);
  background: oklch(25% 0.06 265);
}

/* Movers section */
.movers-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: var(--space-lg);
}

.movers-card {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.movers-card-header {
  padding: var(--space-sm) var(--space-md);
  font-weight: 600;
  font-size: 0.928rem;
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  border-bottom: 1px solid var(--border-subtle);
}

.movers-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid oklch(16% 0.01 270);
  font-size: 0.857rem;
}

.movers-row:last-child {
  border-bottom: none;
}

.movers-row .company {
  font-weight: 500;
}

/* ---- Rating Stars ---- */
.stars {
  display: inline-flex;
  gap: 1px;
  color: oklch(80% 0.15 85);
  font-size: 0.857rem;
}

.stars .empty {
  color: oklch(30% 0.01 270);
}

/* ---- Scrollbar ---- */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}

::-webkit-scrollbar-track {
  background: var(--bg-primary);
}

::-webkit-scrollbar-thumb {
  background: oklch(30% 0.01 270);
  border-radius: 3px;
}

::-webkit-scrollbar-thumb:hover {
  background: oklch(40% 0.01 270);
}

/* ---- Headline Banner ---- */
.headline-banner {
  background: linear-gradient(135deg, oklch(20% 0.04 265), oklch(16% 0.02 270));
  border: 1px solid oklch(25% 0.04 265);
  border-radius: var(--radius-md);
  padding: var(--space-md);
  margin: var(--space-sm) var(--space-md);
  font-size: 0.857rem;
  color: var(--text-secondary);
  line-height: 1.5;
}

.headline-banner strong {
  color: var(--text-primary);
}

/* ---- Responsive ---- */
@media (max-width: 1200px) {
  .chart-workspace {
    grid-template-columns: 1fr;
  }

  .watchlist {
    display: none;
  }
}

@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .grid-3 { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .financials-grid { grid-template-columns: 1fr; }
  .broker-stats { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  html { font-size: 13px; }

  .hero h1 { font-size: 2rem; }
  .hero p { font-size: 1rem; }

  .nav-links { display: none; }

  .grid-2 { grid-template-columns: 1fr; }
  .grid-3 { grid-template-columns: 1fr; }
  .grid-4 { grid-template-columns: 1fr; }

  .movers-grid { grid-template-columns: 1fr; }

  .ideas-grid { grid-template-columns: 1fr; }

  .trending-grid { grid-template-columns: repeat(2, 1fr); }

  .footer-grid { grid-template-columns: 1fr; }

  .detail-stats { grid-template-columns: 1fr; }

  .stats-grid { flex-direction: column; gap: var(--space-lg); align-items: center; }

  .container { padding: 0 var(--space-md); }

  .broker-stats { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 480px) {
  .trending-grid { grid-template-columns: 1fr; }
  .hero-actions { flex-direction: column; }
  .broker-stats { grid-template-columns: 1fr; }
}

/* ---- Animations ---- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  animation: fadeIn 0.4s ease forwards;
}

/* ---- Pre-market tag ---- */
.premarket-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 0.714rem;
  color: var(--text-muted);
  padding: 2px 6px;
  background: oklch(20% 0.01 270);
  border-radius: var(--radius-sm);
}

.premarket-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: oklch(65% 0.14 165);
}

/* ---- Session tabs (Pre/Regular/After) ---- */
.session-tabs {
  display: flex;
  gap: 2px;
}

.session-tab {
  padding: 4px 12px;
  font-size: 0.786rem;
  font-weight: 500;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
}

.session-tab:hover {
  color: var(--text-secondary);
}

.session-tab.active {
  color: var(--text-accent);
  background: oklch(25% 0.06 265);
}

/* ---- Earnings Calendar ---- */
.earnings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  border-bottom: 1px solid oklch(16% 0.01 270);
  font-size: 0.857rem;
}

.earnings-row:last-child {
  border-bottom: none;
}

.earnings-company {
  font-weight: 500;
}

.earnings-eps {
  display: flex;
  gap: var(--space-lg);
  color: var(--text-muted);
  font-variant-numeric: tabular-nums;
}

.earnings-eps .actual {
  color: var(--text-primary);
  font-weight: 600;
}

.earnings-eps .estimate {
  color: var(--text-muted);
}

/* Yield curve mini */
.yield-curve {
  padding: var(--space-md);
}

.yield-bar {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  margin-bottom: var(--space-xs);
}

.yield-bar .label {
  width: 50px;
  font-size: 0.786rem;
  color: var(--text-muted);
  text-align: right;
}

.yield-bar .bar {
  height: 8px;
  border-radius: 4px;
  background: var(--brand-blue);
  transition: width var(--transition-base);
}

.yield-bar .value {
  font-size: 0.786rem;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  min-width: 45px;
}

